{"config":{"title":"blo(c)k","description":"A place where you can read a crazed 16 year old's unfiltered thoughts and torture yourself while at it.","author":"anins1der","plugins":[{"package":"jsr:@steno/plugin-shiki","mode":"trusted"}],"contentDir":"content","output":"dist","custom":{"shortUrls":true,"theme":"jsr:@steno/theme-minimal@^0.9.0","themeConfig":{"author":"anins1der"}}},"theme":{"name":"minimal","version":"0.9.0","config":{"author":"anins1der"},"layouts":[["layout","<!doctype html>
<html lang="en" style="
  {#if theme.accent}--accent: { theme.accent };{/if}
  {#if theme.accentHover}--accent-hover: { theme.accentHover };{/if}
  {#if theme.accentFg}--accent-fg: { theme.accentFg };{/if}
  {#if theme.accentDark}--accent-dark: { theme.accentDark };{/if}
  {#if theme.accentDarkHover}--accent-dark-hover: { theme.accentDarkHover };{/if}
  {#if theme.accentDarkFg}--accent-dark-fg: { theme.accentDarkFg };{/if}
">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>{#if title}{ title }{:else}{ site.title }{/if}</title>
    {#if description}<meta name="description" content={description} />{/if}
    <link rel="stylesheet" href="/assets/style.css" />
  </head>
  <body>
    <header class="site-header">
      <div class="header-container">
        <a href="/" class="site-logo">{#if site.title}{ site.title }{:else}Home{/if}</a>
        {#if site.navigation}
          <nav class="site-nav">
            <ul>
              {#each site.navigation as item}
                <li><a href={item.url}>{ item.title }</a></li>
              {/each}
            </ul>
          </nav>
        {/if}
      </div>
    </header>

    <main class="site-content">
      <article class="content-wrapper">
        {#if date}<p class="page-date">{ date }</p>{/if}
        {@html content}
      </article>
    </main>

    <footer class="site-footer">
      <div class="footer-container">
        <span class="site-mark" aria-hidden="true"></span>
        <p>&copy; {#if site.title}{ site.title }{:else}Steno Site{/if}. Built with Steno.</p>
      </div>
    </footer>
  </body>
</html>
"]],"components":[]},"plugins":[{"name":"steno-plugin-shiki","transformAst":null,"transformHtml":"async (html)=>{
      const highlighter = await highlighterPromise;
      return html.replace(/<pre><code class="language-([\w-]+)">([\s\S]*?)<\/code><\/pre>/g, (_match, lang, rawCode)=>{
        const code = rawCode.replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#39;/g, "'");
        const supportedLangs = highlighter.getLoadedLanguages();
